import React, { useEffect, useState } from "react";

function Incidents() {
  const [incidents, setIncidents] = useState([]);

   useEffect(() => {
  const token = localStorage.getItem(
    "access_token"
  );

  fetch(
    "http://127.0.0.1:8000/incidents",
    {
      headers: {
        Authorization:
          `Bearer ${token}`
      }
    }
  )
    .then((res) => res.json())
    .then((data) => {
      console.log(
        "Incidents:",
        data
      );
      setIncidents(data);
    })
    .catch((err) =>
      console.error(err)
    );
}, []);

  return (
    <div>
      <h1>Incidents</h1>

      {incidents.length === 0 ? (
        <p>No incidents found.</p>
      ) : (
        incidents.map((item, index) => (
          <div
            key={index}
            style={styles.card}
          >
            <h3>{item.title}</h3>
            <p>Status: {item.status}</p>
            <p>Severity: {item.severity}</p>
          </div>
        ))
      )}
    </div>
  );
}

const styles = {
  card: {
    background: "#1e293b",
    padding: "20px",
    marginBottom: "15px",
    borderRadius: "10px",
    color: "white"
  }
};

export default Incidents;
